import {instrumentText} from './instruments.js';
import {LAB_MODULES} from './lab-hardware.js';
import {OLED} from './oled-hardware.js';
import {COMPONENT_ASSETS} from './component-hardware.js';
import {CATALOG,COLORS} from './core.js';
import {ESP_PARTS,espPartDefinition,validateESPCircuit,createESPBench,solveESPCircuit} from './esp-circuit.js';
import {PART_FIELDS,partDefaults} from './part-parameters.js';
const NS='http://www.w3.org/2000/svg';
const svg=(tag,attributes={})=>{const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attributes))e.setAttribute(k,v);return e;};
export class ESPCircuitEditor {
 constructor({canvas,properties,parts,changed,status,chip,project}){Object.assign(this,{canvas,properties,parts,changed,status,chip});this.project=validateESPCircuit(project||createESPBench(chip),chip);this.view={x:0,y:0,w:900,h:530};this.selected=null;this.pending=null;this.snapshot=null;this.undoStack=[];this.redoStack=[];this.drag=null;
  for(const type of ESP_PARTS){const option=document.createElement('option');option.value=type;option.textContent=CATALOG[type].name;parts.append(option);}
  canvas.addEventListener('pointerdown',e=>this.pointerDown(e));canvas.addEventListener('pointermove',e=>this.pointerMove(e));canvas.addEventListener('pointerup',e=>this.pointerUp(e));canvas.addEventListener('pointercancel',()=>{this.drag=null;});canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom(e.deltaY>0?1.15:1/1.15);},{passive:false});canvas.addEventListener('keydown',e=>{if(e.key==='Escape'){this.pending=null;this.draw();}if(e.key==='Delete'){e.preventDefault();this.remove();}});this.draw();this.inspect();
 }
 point(event,matrix=this.canvas.getScreenCTM().inverse()){const point=this.canvas.createSVGPoint();point.x=event.clientX;point.y=event.clientY;return point.matrixTransform(matrix);}
 remember(){this.undoStack.push(structuredClone(this.project));if(this.undoStack.length>40)this.undoStack.shift();this.redoStack=[];}
 commit(inspect=true){this.project=validateESPCircuit(this.project,this.chip);this.changed(structuredClone(this.project));this.draw();if(inspect)this.inspect();else this.readings();}
 set(chip,project){this.chip=chip;this.project=validateESPCircuit(project,chip);this.snapshot=null;this.selected=null;this.pending=null;this.undoStack=[];this.redoStack=[];this.fit();this.inspect();}
 add(){if(this.project.components.length>=80)return this.status('En çok 80 bileşen eklenebilir.');this.remember();const type=this.parts.value;let i=1;while(this.project.components.some(c=>c.id===type+i))i++;const params={...partDefaults(type),...(type==='resistor'?{ohms:220}:type==='button'?{pressed:false}:type==='pot'?{value:50,ohms:10000}:type==='supply'?{voltage:3.3}:type==='led'?{color:'red'}:{})};const c={id:type+i,type,x:Math.round(this.view.x+this.view.w*.5),y:Math.round(this.view.y+this.view.h*.4),params};this.project.components.push(c);this.selected={kind:'part',id:c.id};this.commit();}
 clear(){this.remember();this.project.components=this.project.components.filter(c=>c.type==='board');this.project.wires=[];this.selected=null;this.pending=null;this.commit();}
 remove(){if(!this.selected)return;const s=this.selected;if(s.kind==='part'&&this.project.components.find(c=>c.id===s.id)?.type==='board')return this.status('MCU kartı silinemez.');this.remember();if(s.kind==='wire')this.project.wires=this.project.wires.filter(w=>w.id!==s.id);else{this.project.components=this.project.components.filter(c=>c.id!==s.id);this.project.wires=this.project.wires.filter(w=>!w.from.startsWith(s.id+':')&&!w.to.startsWith(s.id+':'));}this.selected=null;this.pending=null;this.commit();}
 undo(){if(!this.undoStack.length)return;this.redoStack.push(structuredClone(this.project));this.project=this.undoStack.pop();this.selected=null;this.pending=null;this.commit();}
 redo(){if(!this.redoStack.length)return;this.undoStack.push(structuredClone(this.project));this.project=this.redoStack.pop();this.selected=null;this.pending=null;this.commit();}
 zoom(scale){const w=Math.max(250,Math.min(3000,this.view.w*scale)),ratio=w/this.view.w;this.view={x:this.view.x+(this.view.w-w)/2,y:this.view.y+this.view.h*(1-ratio)/2,w,h:this.view.h*ratio};this.draw();}
 fit(){const boxes=this.project.components.map(c=>{const d=espPartDefinition(c,this.chip);return{x:c.x,y:c.y,w:d.width,h:d.height};}),x=Math.min(...boxes.map(b=>b.x))-30,y=Math.min(...boxes.map(b=>b.y))-30,right=Math.max(...boxes.map(b=>b.x+b.w))+30,bottom=Math.max(...boxes.map(b=>b.y+b.h))+30;this.view={x,y,w:Math.max(650,right-x),h:Math.max(400,bottom-y)};this.draw();}
 endpoint(endpoint){const [id,pin]=endpoint.split(':'),c=this.project.components.find(c=>c.id===id),p=espPartDefinition(c,this.chip).pinDefs.find(p=>p.id===pin);return{x:c.x+p.x,y:c.y+p.y};}
 connect(endpoint){if(this.pending&&this.pending!==endpoint&&this.project.wires.length>=300){this.pending=null;this.draw();return this.status('En çok 300 kablo eklenebilir.');}if(!this.pending){this.pending=endpoint;this.status('İkinci pini seçin · Esc iptal');}else if(this.pending!==endpoint){if(!this.project.wires.some(w=>(w.from===this.pending&&w.to===endpoint)||(w.to===this.pending&&w.from===endpoint))){this.remember();let i=1;while(this.project.wires.some(w=>w.id==='wire'+i))i++;this.project.wires.push({id:'wire'+i,from:this.pending,to:endpoint,color:COLORS[0]});this.commit();}this.pending=null;this.status('Kablo bağlandı');}else this.pending=null;this.draw();}
 pointerDown(e){const pin=e.target.closest('[data-pin]');if(pin){e.preventDefault();this.connect(pin.dataset.pin);return;}const wire=e.target.closest('[data-wire]');if(wire){this.selected={kind:'wire',id:wire.dataset.wire};this.draw();this.inspect();return;}const part=e.target.closest('[data-part]');this.selected=part?{kind:'part',id:part.dataset.part}:null;this.inspect();this.draw();const p=this.point(e);if(part){const c=this.project.components.find(c=>c.id===part.dataset.part);this.remember();this.drag={id:c.id,start:p,x:c.x,y:c.y,moved:false};}else this.drag={pan:true,start:p,x:this.view.x,y:this.view.y};this.drag.matrix=this.canvas.getScreenCTM().inverse();this.canvas.setPointerCapture(e.pointerId);}
 pointerMove(e){if(!this.drag)return;const p=this.point(e,this.drag.matrix),d=this.drag;if(d.pan){this.view.x=d.x-(p.x-d.start.x);this.view.y=d.y-(p.y-d.start.y);}else{const c=this.project.components.find(c=>c.id===d.id);c.x=Math.max(-9000,Math.min(9000,Math.round(d.x+p.x-d.start.x)));c.y=Math.max(-9000,Math.min(9000,Math.round(d.y+p.y-d.start.y)));d.moved=true;}this.draw();}
 pointerUp(){if(!this.drag)return;const changed=!this.drag.pan&&this.drag.moved;this.drag=null;if(changed)this.commit();}
 update(snapshot){this.snapshot=snapshot;for(const c of this.project.components){const group=this.canvas.querySelector('[data-part="'+c.id+'"]');if(!group)continue;if(c.type==='led'){const current=snapshot.leds?.[c.id]?.current,light=group.querySelector('[data-led-light]'),text=group.querySelector('[data-led-current]');if(light)light.setAttribute('opacity',current>1e-5?Math.min(1,current/.005):0);if(text)text.textContent=current!=null?(current*1000).toFixed(2)+' mA':'— mA';}if(c.type==='multimeter'){const text=group.querySelector('[data-meter-text]');if(text)text.textContent=instrumentText(snapshot.meters?.[c.id]||{status:'OL'});}if(['relay','coilRelay'].includes(c.type)){const text=group.querySelector('[data-contact-text]');if(text)text.textContent=snapshot.contacts?.[c.id]?.energized?'ON · COM→NO':'OFF · COM→NC';}if(c.type==='oled'){const d=snapshot.devices?.[c.id],screen=group.querySelector('[data-display]');if(d?.frame&&screen&&screen.dataset.revision!==String(d.revision)){screen.dataset.revision=String(d.revision);this.display(screen,d.frame);}}}for(const w of this.project.wires){const title=this.canvas.querySelector('[data-wire="'+w.id+'"] title');if(title)title.textContent=w.from+' → '+w.to+' · '+(snapshot.wireVoltages?.[w.id]?.toFixed(3)??'—')+' V';}this.readings();}
 display(screen,frame){screen.replaceChildren(svg('rect',{x:0,y:0,width:128,height:64,fill:'#07121c'}));for(let page=0;page<8;page++)for(let x=0;x<128;x++){const byte=frame[page*128+x]||0;for(let bit=0;bit<8;bit++)if(byte&(1<<bit))screen.append(svg('rect',{x,y:page*8+bit,width:1,height:1,fill:'#4fdaef'}));}}
 draw(){this.canvas.setAttribute('viewBox',[this.view.x,this.view.y,this.view.w,this.view.h].join(' '));this.canvas.replaceChildren();const defs=svg('defs'),pattern=svg('pattern',{id:'esp-circuit-grid',width:20,height:20,patternUnits:'userSpaceOnUse'});pattern.append(svg('circle',{cx:1,cy:1,r:1,fill:'#344354'}));defs.append(pattern);this.canvas.append(defs,svg('rect',{x:this.view.x,y:this.view.y,width:this.view.w,height:this.view.h,fill:'url(#esp-circuit-grid)'}));
  for(const w of this.project.wires){const a=this.endpoint(w.from),b=this.endpoint(w.to),path=svg('path',{d:`M${a.x} ${a.y}H${(a.x+b.x)/2}V${b.y}H${b.x}`,stroke:w.color,'stroke-width':this.selected?.id===w.id?5:2.5,fill:'none','data-wire':w.id,role:'button',tabindex:0,'aria-label':'Kablo '+w.from+' → '+w.to});const title=svg('title');title.textContent=w.from+' → '+w.to+' · '+(this.snapshot?.wireVoltages?.[w.id]?.toFixed(3)??'—')+' V';path.append(title);path.addEventListener('keydown',e=>{if(e.key==='Enter'){this.selected={kind:'wire',id:w.id};this.draw();this.inspect();}});this.canvas.append(path);}
  for(const c of this.project.components){const d=espPartDefinition(c,this.chip),g=svg('g',{'data-part':c.id,transform:`translate(${c.x} ${c.y})`,role:'button',tabindex:0,'aria-label':d.name+' '+c.id});if(this.selected?.kind==='part'&&this.selected.id===c.id)g.append(svg('rect',{x:-5,y:-5,width:d.width+10,height:d.height+10,rx:7,fill:'none',stroke:'#55bdf1','stroke-width':2}));let asset=d.asset;if(c.type==='button'&&c.params.pressed)asset=COMPONENT_ASSETS.button.pressedAsset;if(c.type==='resistor')asset=COMPONENT_ASSETS.resistor.variants[c.params.ohms]||d.asset;if(c.type==='led')asset=COMPONENT_ASSETS.led.variants[c.params.color]||d.asset;if(asset)g.append(svg('image',{href:'./assets/'+asset,width:d.width,height:d.height}));else g.append(svg('rect',{width:d.width,height:d.height,rx:6,fill:'#263342',stroke:'#8398aa'}));
   const label=svg('text',{x:0,y:-9,fill:'#a8c4d6','font-size':11,'font-family':'Consolas,monospace'});label.textContent=c.id+' · '+d.name+(c.type==='resistor'?' · '+c.params.ohms+' Ω':c.type==='zener'?' · '+(c.params.vz??5.1)+' V':'');g.append(label);
   if(c.type==='led'){const current=this.snapshot?.leds?.[c.id]?.current;g.append(svg('circle',{cx:27.4,cy:26.4,r:17,fill:'#ff5369',opacity:current>1e-5?Math.min(1,current/.005):0,'data-led-light':''}));const t=svg('text',{x:0,y:d.height+18,fill:'#82d3ba','font-size':12,'data-led-current':''});t.textContent=current!=null?(current*1000).toFixed(2)+' mA':'— mA';g.append(t);}
   if(c.type==='multimeter'){const r=LAB_MODULES.multimeter.display,t=svg('text',{x:(r.x+r.width/2)*d.scale,y:(r.y+r.height*.55)*d.scale,fill:'#91f7cb','font-size':16*d.scale,'text-anchor':'middle','font-family':'Consolas,monospace','data-meter-text':''});t.textContent=instrumentText(this.snapshot?.meters?.[c.id]||{status:'OL'});g.append(t);}if(['relay','coilRelay'].includes(c.type)){const t=svg('text',{x:0,y:d.height+18,fill:'#82d3ba','font-size':11,'data-contact-text':''});t.textContent=this.snapshot?.contacts?.[c.id]?.energized?'ON · COM→NO':'OFF · COM→NC';g.append(t);}if(c.type==='oled'){const device=this.snapshot?.devices?.[c.id],screen=svg('g',{'data-display':'','data-revision':device?.revision??'',transform:`translate(${OLED.display.x*d.scale} ${OLED.display.y*d.scale}) scale(${OLED.display.width*d.scale/128} ${OLED.display.height*d.scale/64})`});if(device?.frame)this.display(screen,device.frame);g.append(screen);}
   for(const p of d.pinDefs){if(p.connectable===false)continue;const endpoint=c.id+':'+p.id,circle=svg('circle',{cx:p.x,cy:p.y,r:c.type==='board'?5.5:5,fill:this.pending===endpoint?'#efd453':'#b5a677',stroke:'#101b24','stroke-width':1,'data-pin':endpoint,role:'button',tabindex:0,'aria-label':c.id+' '+p.id+' pin'}),title=svg('title');title.textContent=c.id+':'+p.id;circle.append(title);circle.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();this.connect(endpoint);}});g.append(circle);}
   g.addEventListener('keydown',e=>{if(e.target===g&&e.key==='Enter'){this.selected={kind:'part',id:c.id};this.draw();this.inspect();}});this.canvas.append(g);
  }
 }
 inspect(){this.properties.replaceChildren();const heading=document.createElement('strong');heading.textContent=this.selected?.id||'Devre özellikleri';this.properties.append(heading);
  if(this.selected?.kind==='wire'){const w=this.project.wires.find(w=>w.id===this.selected.id);const text=document.createElement('p');text.textContent=w.from+' → '+w.to;this.properties.append(text);const color=document.createElement('select');color.setAttribute('aria-label','Kablo rengi');for(const value of COLORS){const o=document.createElement('option');o.value=value;o.textContent=value;color.append(o);}color.value=w.color;color.onchange=()=>{this.remember();w.color=color.value;this.commit();};this.properties.append(color);}
  else if(this.selected?.kind==='part'){const c=this.project.components.find(c=>c.id===this.selected.id),fields=[...(PART_FIELDS[c.type]||[]),...(c.type==='spdt'?[{key:'position',label:'Kontak',value:'left',options:[['left','1 ↔ 2'],['right','2 ↔ 3']]}]:c.type==='oled'?[{key:'address',label:'I²C adres',value:60,options:[[60,'0x3C'],[61,'0x3D']]}]:c.type==='relay'?[{key:'activeHigh',label:'Aktif giriş',value:true,options:[[true,'HIGH'],[false,'LOW']]}]:c.type==='led'?[{key:'color',label:'Renk',value:'red',options:[['red','Kırmızı'],['green','Yeşil'],['blue','Mavi'],['yellow','Sarı'],['white','Beyaz']]}]:[]),...(c.type==='resistor'?[{key:'ohms',label:'Direnç (Ω)',min:.001,max:1e7,step:1}]:c.type==='pot'?[{key:'value',label:'Konum (%)',min:0,max:100,step:1}]:c.type==='supply'?[{key:'voltage',label:'Gerilim (V)',min:0,max:30,step:.1}]:c.type==='button'?[{key:'pressed',label:'Buton basılı',options:[[false,'Bırakıldı'],[true,'Basılı']]}]:[])];for(const f of fields){const label=document.createElement('label');label.textContent=f.label;const input=document.createElement(f.options?'select':'input');input.setAttribute('aria-label',c.id+' '+f.label);if(f.options)for(const[value,name]of f.options){const o=document.createElement('option');o.value=String(value);o.textContent=name;input.append(o);}else{input.type='number';input.min=f.min;input.max=f.max;input.step=f.step||'any';}input.value=String(c.params[f.key]??f.value??0);input[f.options?'onchange':'oninput']=()=>{const candidate=structuredClone(this.project),next=candidate.components.find(p=>p.id===c.id),value=f.options?f.options.find(o=>String(o[0])===input.value)?.[0]:Number(input.value);next.params[f.key]=value;try{validateESPCircuit(candidate,this.chip);this.remember();this.project=candidate;this.commit(false);}catch(error){this.status(error.message,true);input.value=String(this.project.components.find(p=>p.id===c.id).params[f.key]??f.value??0);}};label.append(input);this.properties.append(label);}}
  else{const p=document.createElement('p');p.textContent='Bileşeni sürükleyin. Kablo için iki pini seçin. Kaydırma: yakınlaşma; boş alanı sürükleme: gezinme.';this.properties.append(p);}const readings=document.createElement('pre');readings.id='esp-circuit-readings';this.properties.append(readings);this.readings();
 }
 readings(){const panel=this.properties.querySelector('#esp-circuit-readings');if(!panel)return;const s=this.snapshot,d=s?.devices?.[this.selected?.id];panel.textContent=d?JSON.stringify({...d,frame:undefined},null,2):s&&this.selected?.kind==='part'?JSON.stringify({pinVolts:s.partPins?.[this.selected.id],sensor:s.sensors?.[this.selected.id],contact:s.contacts?.[this.selected.id],meter:s.meters?.[this.selected.id]},null,2):s?'DC ağ geçerli · I²C ACK '+s.bus.addressACK+' / NACK '+s.bus.addressNACK:'';}
}
